mapper.select:
SELECT o.id FROM orders o INNER JOIN order_items oi ON oi.order_id = o.id WHERE o.user_id = #{user_id} AND oi.product_id = #{product_id} AND o.payment_status = 'PAID' AND o.status = 'DELIVERED'
AND o.id = #{order_id}
AND NOT EXISTS ( SELECT 1 FROM reviews r WHERE r.user_id = o.user_id AND r.product_id = oi.product_id AND r.order_id = o.id AND r.is_active = 1 ) ORDER BY o.ordered_at DESC, o.id DESC LIMIT 1

